\label{thm:main}
Let $X$ be a connected compact K\"ahler manifold with semi-ample
canonical bundle, and let $[{\omega}]$  be any K\"ahler class.
For all sufficiently small $\varepsilon>0$, let
$\omega_\varepsilon\in 2\pi c_1(K_X)+\varepsilon [{\omega}] $ be the unique cscK metric. If $m=0$, the metrics converge to a point in the Gromov-Hausdorff topology. If $m>0$, then:\begin{enumerate}
    \item For any compact $K\Subset Y^\circ$, 
    \begin{equation}
        \|\omega_\varepsilon-(f^*\omega_{\rm can}+\varepsilon\omega_{\rm SRF})\|_{f^*\omega_{\rm can}+\varepsilon{\omega}}\to 0 \quad \text{uniformly on }f^{-1}(K).
    \end{equation}
    \item Let $d_{\omega_{\varepsilon}}$ be {the distance function induced by the metric} $\omega_{\varepsilon}$ on $X$, \begin{equation}\label{eq:gh}
(X,d_{\omega_\varepsilon})
 \longrightarrow (\overline{Y^\circ},d_{\rm can})
 \qquad\text{in the Gromov--Hausdorff topology}.
 \end{equation}
\end{enumerate}

\label{thm:completion}
For the semi-ample canonical fibration with $m>0$, the completion
$\overline{Y^\circ}=\overline{(Y^\circ,d_{\rm can})}$ satisfies:
\begin{enumerate}
\item\label{item:thm-completion-1} $\overline{Y^\circ}$ is compact and canonically homeomorphic to $Y$.
\item\label{item:thm-completion-2} $(Y,d_{\rm can},\nu_{\rm can})$ is a noncollapsed
$\operatorname{RCD}(-1,2m)$ space. 
\item\label{item:thm-completion-3}
$\dim_{\mathcal H}(Y\setminus Y^\circ)\leq2m-2$.
\end{enumerate}

\label{thm:bounds}
There are constants $C,\varepsilon_0,a_{\rm vol}>0$ such that
for $0<\varepsilon<\varepsilon_0$:
\begin{enumerate}
\item\label{item:thm-bounds-1}
$\|\varphi_\varepsilon\|_\infty+\|F_\varepsilon\|_\infty\leq C$,
and hence $C^{-1}\Omega\leq{d\mu_\varepsilon}\leq C\Omega$.
\item\label{item:thm-bounds-2} $\operatorname{diam}(X,\omega_\varepsilon)\leq C$.
\item\label{item:thm-bounds-3}
$\mu_\varepsilon(B_{\omega_\varepsilon}(x,r))\geq C^{-1}r^{a_{\rm vol}}$
for $x\in X$, $0<r<1$. Consequently the family is GH precompact.
\end{enumerate}

\label{thm:NKRF-convergence}
\leavevmode
\begin{enumerate}
    \item $|{\tilde\varphi}(t)|+|\partial_t{\tilde\varphi}(t)|\leq C$ and $C^{-1}e^{-dt}{\omega}^n\leq ({\tilde\omega}(t))^n\leq Ce^{-dt}{\omega}^n$. {See Song--Tian} \cite[Lemma~2.1 and Proposition~2.1]{ST16}{; the volume bounds follow from the scalar flow equation and these potential bounds.}
    \item ${\tilde\varphi}(t)\to f^*\varphi_{\rm can}$ and $\partial_t{\tilde\varphi}\to 0$ uniformly on every compact set of $X^\circ,$ and in $L^p(X,\Omega)$ for any $1\le p<\infty$. {For convergence of the potential, see Song--Tian} \cite[Proposition~5.4]{ST12}{; for convergence of the time derivative on the regular locus, see Tosatti--Weinkove--Yang} \cite[Lemma~3.1(ii), (iv)]{TWY18}{. The finite-}$L^p${ convergence follows from part (1) and dominated convergence.}
    \item $\|{\tilde\omega}(t)-(e^{-t}\omega_{\rm SRF}+(1-e^{-t})f^*\omega_{\rm can})\|_{{\tilde\omega}(t)}\to 0$ on every compact subset of $X^\circ$. {See Tosatti--Weinkove--Yang} \cite[Section~3.3, proof of Theorem~1.2(i), immediately after equation~(3.22)]{TWY18}{, where this relative-norm convergence is established using Lemma~2.6.}
\end{enumerate}

\label{lem:trace-lp}
Let $\Phi:X\to Z$ be a holomorphic map from a compact complex manifold {$X$}
to a fixed compact K\"ahler manifold $(Z,\omega_Z)$, and put
$\chi=\Phi^*\omega_Z$. Suppose that $\omega_\varphi$, $F$, and a constant
$\underline R$ satisfy
\begin{equation}\label{eq:ht1}
 \operatorname{Ric}(\omega_\varphi)=-\chi-dd^cF,\qquad
 \Delta_\varphi F=-\underline R-\operatorname{tr}_\varphi\chi.
\end{equation}
If $|\underline R|+\operatorname{osc}_X F\leq C_0$, then, for every
finite $p\geq1$,
\begin{equation}\label{eq:ht2}
\int_X(\operatorname{tr}_\varphi\chi)^p\,d\mu\leq C_p.
\end{equation}
The constant {$C_p$} depends only on $p,C_0$ and an upper bound for the
holomorphic bisectional curvature of $\omega_Z$.

\label{lem:gradient}
Under the same assumptions in Lemma~\ref{lem:trace-lp},
\begin{equation}\label{eq:c-18b}
 \sup_X|\nabla_\varphi F|_\varphi^2\leq C'.
\end{equation}

\label{lem:am-limit}
\leavevmode
\begin{enumerate}
        \item $E_\varepsilon(\varphi_\varepsilon)\to E_Y(u)$.
        \item $u$ maximizes the functional $E_Y(\varphi)-\int_Y\varphi d\nu$.
        \item $\operatorname{MA}_Y(u)=\nu$.
    \end{enumerate}

\label{lem:mix-current}\leavevmode
\begin{enumerate}
\item\label{item:mixed-local} On $Y^\circ$,
\begin{equation}\label{eq:c-6}
f_*\left(\frac{\omega_\varepsilon^{n-1}}{V_\varepsilon}\right)\rightharpoonup\frac{m}{nV_Y}(\chi_Y+dd^cu)^{m-1}.
\end{equation}
\item\label{item:mixed-global} On $Y$,
\begin{equation}\label{eq:c-7}
f_*\left(\frac{\chi\wedge\omega_\varepsilon^{n-1}}{V_\varepsilon}\right)\rightharpoonup\frac{m}{nV_Y}\chi_Y\wedge(\chi_Y+dd^cu)^{m-1}.
\end{equation}
\end{enumerate}

\label{lem:iteration}
Fix $q/(q-1)<p_*<\infty$. 
Every smooth real function $U$ on $f^{-1}(B_{2r})$ satisfies
\begin{equation}
\|U\|_{L^\infty(f^{-1}(B_r))}
 \leq C\left(\|U\|_{L^2(f^{-1}(B_{2r}),\mu_\varepsilon)}+\|\Delta_{\omega_\varepsilon}U\|_{L^{p_*}(f^{-1}(B_{2r}),\mu_\varepsilon)}
 \right).
\end{equation}
The constant depends only on $p_*$ and the fixed chart.

\label{lem:local-potential}

Let $\mathcal P\subset\mathbb C^N$ be a fixed polydisc. A smooth closed real
$(1,1)$-form $\alpha$ on a neighborhood of $\overline{\mathcal P}$,
has a real potential $b\in C^\infty(\mathcal P)$ such that
\begin{equation}
dd^c b=\alpha,\qquad
\|b\|_{L^\infty(\mathcal P)}\leq C_{\mathcal P}\|\alpha\|_{L^\infty(\mathcal P)}.
\end{equation}
Here the norms of forms are Euclidean tensor norms.

\label{lem:metric-convergence}For every compact $K\Subset Y^\circ$, \begin{enumerate}
    \item $\|\omega_{\varepsilon}-
    (f^*\omega_{\rm can}+\varepsilon\omega_{\rm SRF})\|_{f^*\omega_{\rm can}+\varepsilon{\omega}}\to 0$ uniformly on $f^{-1}(K)$.
    \item $\sup_{y\in K}\operatorname{diam}(X_y,\omega_\varepsilon|_{X_y})\leq C_K\sqrt{\varepsilon}.$
\end{enumerate}

\label{lem:ltz-distance}
For $0<m\leq n$:
\begin{enumerate}
\item(\cite[Lemma~4.1]{LTZ26})
For every $\delta>0$, there is a compact $K\Subset Y^\circ$,
independent of $\varepsilon$, such that, for all sufficiently small
$\varepsilon>0$,
\[
 \sup_{y\in Y}d_{\rm can}(y,K)<\delta,\qquad
 \sup_{x\in X}d_{\omega_\varepsilon}(x,f^{-1}(K))<\delta.
\]

\item(\cite[equation~(4.14), using Lemma~4.2]{LTZ26})\label{item:ltz-regular-upper}
For every compact $K\Subset Y^\circ$,
\begin{equation}
 \sup_{x,x'\in f^{-1}(K)}
 \bigl(d_{\omega_\varepsilon}(x,x')
       -d_{\rm can}(f(x),f(x'))\bigr)_+\longrightarrow0.
\end{equation}
\end{enumerate}

\label{prop:distortion}\label{prop:upper-distance}
For $0<m\leq n$:
\begin{enumerate}
\item\label{item:distortion-uniform}
\[
 \sup_{x,x'\in X}\left|d_{\omega_\varepsilon}(x,x') -d_{\rm can}(f(x),f(x'))\right|\longrightarrow0.
\]
\item\label{item:distortion-gh}
\[
 d_{\rm GH}\bigl((X,d_{\omega_\varepsilon}),(Y,d_{\rm can})\bigr)\longrightarrow0.
\]
\end{enumerate}

By Lemma~\ref{lem:sharp-lip}, we can choose $\lambda>1$ such that the solution $\Delta h_v
=\lambda h_v+v$, satisfies \[
\operatorname{Lip}(\lambda h_v)\leq \frac{\lambda}{\lambda-1/2}\operatorname{Lip}(v)\leq 1+\frac{\delta}{3},\qquad \|\lambda h_v+v\|_{L^\infty} \leq \frac{\delta}{3}.
\]

By Stone-Weierstrass theorem, the smooth function on $\mathbb C P^N$ are dense in $C(Y)$. So we can choose such $g_0\in C^\infty(\mathbb C P^N)$ such that $\|g_0-v\|_{L^\infty}<\min\{\delta/3,\delta/(3\lambda C_\lambda)\},$ and set $ g=-\lambda g_0.$ Then we have 
\begin{align*}
 \|h-v\|_{L^\infty}
 &\leq\|h+\lambda h_v\|_{L^\infty}
          +\|\lambda h_v+v\|_{L^\infty}\leq\lambda C_\lambda\|g_0-v\|_{L^\infty}+ \frac{\delta}{3}\leq \frac{3\delta}{3},\\
 \operatorname{Lip}(h)
 &\leq\operatorname{Lip}(\lambda h_v)
          +\lambda C_\lambda\|g_0-v\|_\infty<1+2\delta/3.\qedhere
\end{align*}

\label{lem:krf-uniform}
There exist $q>1$ and constants independent of $t\geq0$ such that:
\begin{enumerate}
\item\label{item:krf-density-gradient}
\[
 C^{-1}\leq e^{F(t)}\leq C,\qquad\operatorname{tr}_{{\tilde\omega}(t)}\chi+|\nabla F(t)|_{{\tilde\omega}(t)}^2\leq C.
\]
\item\label{item:krf-sobolev}
For every $v\in W^{1,2}(X,{\tilde\omega}(t))$,
\begin{equation}\label{eq:krf-sobolev}
 \left(\int_X|v|^{2q}\,d\mu_t\right)^{1/q}
 \leq C\int_X\bigl(|\nabla v|_{{\tilde\omega}(t)}^2+v^2\bigr)\,d\mu_t.
\end{equation}
\item\label{item:krf-volume-diameter}
For $x\in X$ and $0<r\leq1$,
\begin{equation}\label{eq:krf-volume-diameter}
 \mu_t(B_{{\tilde\omega}(t)}(x,r))\geq C^{-1}r^{2q/(q-1)},\qquad
 \operatorname{diam}(X,{\tilde\omega}(t))\leq C.
\end{equation}
\end{enumerate}

\label{lem:krf-resolvent-energy}
Put $e_t=h_t-f^*h$. Then:
\begin{enumerate}
\item\label{item:krf-resolvent-uniform}
$\|e_t\|_\infty\to0$.
\item\label{item:krf-resolvent-energy}
For every $K\Subset Y^\circ$,
\[
 \int_{f^{-1}(K)}|\nabla e_t|_{{\tilde\omega}(t)}^2\,d\mu_t\longrightarrow0.
\]
\end{enumerate}
